document.addEventListener("DOMContentLoaded",function(){if(window.FCFDiscovery){var e=document.getElementById("hub-featured-mount");if(e){var t=Array.prototype.slice.call(document.querySelectorAll("[data-hub-featured-eligible]"));if(t.length){var a=location.pathname.split("/").pop()||"hub",r=window.FCFDiscovery.pickWeekly(t,a+"|hub-featured");if(r){var l=r.cloneNode(!0);l.removeAttribute("data-hub-featured-eligible"),l.removeAttribute("id");for(var d=l.querySelectorAll?l.querySelectorAll("[id]"):[],o=0;o<d.length;o++)d[o].removeAttribute("id");"DETAILS"===l.tagName&&(l.open=!0);for(var n=l.querySelectorAll?l.querySelectorAll("details"):[],i=0;i<n.length;i++)n[i].open=!0;var u=document.createElement("div");u.className="hub-featured-wrap",u.innerHTML='<span class="hub-featured-label"><span class="hub-featured-dot"></span>Featured This Week</span>',u.appendChild(l),e.appendChild(u)}}}}});